    name_tr, name_en, scientific_name, water_type, active_seasons, recommended_gear,
    description_tr, description_en, limit_size, ban_periods, short_info_tr, short_info_en,
    favorite_baits, primary_regions, taste_rating, cooking_tips_tr, cooking_tips_en
