)
INSERT INTO public.fishes (
  name_tr, name_en, scientific_name, water_type, active_seasons, recommended_gear,
  description_tr, description_en, image_url, is_active, created_at, limit_size, ban_periods,
  short_info_tr, short_info_en, favorite_baits, primary_regions, taste_rating, cooking_tips_tr, cooking_tips_en
)
SELECT
  nf.name_tr, nf.name_en, nf.scientific_name, nf.water_type, nf.active_seasons, nf.recommended_gear,
  nf.description_tr, nf.description_en, NULL, true, timezone('utc'::text, now()), nf.limit_size, nf.ban_periods,
  nf.short_info_tr, nf.short_info_en, nf.favorite_baits, nf.primary_regions, nf.taste_rating, nf.cooking_tips_tr, nf.cooking_tips_en
FROM new_fishes nf
WHERE NOT EXISTS (
  SELECT 1
  FROM public.fishes f
  WHERE lower(f.scientific_name) = lower(nf.scientific_name)
     OR lower(f.name_tr) = lower(nf.name_tr)
);

NOTIFY pgrst, 'reload schema';
